STR["hi"].update({"newsTitle":"आज का टोक्यो","newsUpdated":"{t} अपडेट","newsFly":"उड़कर जाएँ","newsYesterday":"कल का टोक्यो","newsCountFmt":"कुल {n} सूचनाएँ","newsLv_alert":"चेतावनी","newsLv_traffic":"यातायात","newsLv_event":"केवल आज","newsLv_news":"समाचार","newsFlash":"बुलेटिन","newsEmpty":"आज कोई सूचना नहीं","newsItemsFmt":"{n} सूचनाएँ"})

# split narration scripts (narr_<spotid>) out of STR into a separate file
IDS_SET = set(IDS)
NARR = {}
for _lang, _d in STR.items():
    _scripts = {}
    for _k in [k for k in list(_d.keys()) if k.startswith("narr_") and k[5:] in IDS_SET]:
        _scripts[_k[5:]] = _d.pop(_k)
    NARR[_lang] = _scripts

out = {
 "str": STR,
 "names": {lang: dict(zip(IDS, vals)) for lang, vals in NAMES.items()},
 "areas": AREAS,
}
p = pathlib.Path(__file__).parent.parent / "data" / "i18n_ui.js"
p.parent.mkdir(parents=True, exist_ok=True)
p.write_text("window.I18NUI=" + json.dumps(out, ensure_ascii=False, separators=(",", ":")) + ";\n", encoding="utf-8")
print("wrote", p, p.stat().st_size, "bytes")
# sanity: identical key sets
base = set(STR["zh"].keys())
for lang, d in STR.items():
    assert set(d.keys()) == base, (lang, set(d.keys()) ^ base)
    assert len(d["relDays"]) == 4 and len(d["wxCond"]) == 17
    assert set(d["tourNames"].keys()) == {"classic","trendy","night","culture"}
for lang, m in out["names"].items(): assert len(m) == 34, lang
for lang, a in AREAS.items(): assert len(a) == 17, lang
print("sanity OK: keys consistent across 5 languages")
_np = pathlib.Path(__file__).parent.parent / "data" / "narr_ui.js"
_np.write_text("window.I18NNARR=" + json.dumps(NARR, ensure_ascii=False, separators=(",", ":")) + ";\n", encoding="utf-8")
print("wrote", _np, _np.stat().st_size, "bytes")
_base_narr = set(NARR["zh"].keys())
for _lang, _d in NARR.items():
    assert set(_d.keys()) == _base_narr, _lang
assert len(_base_narr) == 34, len(_base_narr)
print("narration sanity OK: 34 scripts x 5 languages")
